cd D:/Repos/angular-jig && set -e
mk() { # dir Name Title
  d=src/app/$1; mkdir -p $d
  cat > $d/$1.ts <<EOF
import { Component } from '@angular/core';

// Placeholder. The $3 screen is built in a later stage.
@Component({
  selector: 'app-$1',
  templateUrl: './$1.html',
  styleUrl: './$1.css',
})
export class $2 {}
EOF
  cat > $d/$1.html <<EOF
<section class="$1">
  <h1 class="$1__title">$3</h1>
  <p class="$1__note">Placeholder screen.</p>
</section>
EOF
  cat > $d/$1.css <<EOF
@reference "../../styles.css";

.$1 { @apply grid grid-cols-1 gap-2; }
.$1__title { @apply text-2xl font-semibold; }
.$1__note { @apply text-sm text-muted-foreground; }
EOF
}
mk missions Missions Missions
mk threats Threats Threats
mk recruit Recruit Recruit
mk settings Settings Settings
cat > src/app/app.routes.ts <<'EOF'
import { Routes } from '@angular/router';

export const routes: Routes = [
  { path: '', pathMatch: 'full', redirectTo: 'dashboard' },
  {
    path: 'dashboard',
    loadComponent: () => import('./dashboard/dashboard').then((m) => m.Dashboard),
  },
  {
    path: 'roster',
    loadComponent: () => import('./heroes/heroes').then((m) => m.Heroes),
  },
  // The roster used to live at /heroes; keep old links working.
  { path: 'heroes', redirectTo: 'roster' },
  {
    path: 'detail/:id',
    loadComponent: () => import('./hero-detail/hero-detail').then((m) => m.HeroDetail),
  },
  {
    path: 'missions',
    loadComponent: () => import('./missions/missions').then((m) => m.Missions),
  },
  {
    path: 'threats',
    loadComponent: () => import('./threats/threats').then((m) => m.Threats),
  },
  {
    path: 'recruit',
    loadComponent: () => import('./recruit/recruit').then((m) => m.Recruit),
  },
  {
    path: 'settings',
    loadComponent: () => import('./settings/settings').then((m) => m.Settings),
  },
];
EOF
python3 - <<'EOF'
p='src/index.html'
s=open(p,encoding='utf-8').read()
s=s.replace('  <app-root></app-root>','  <script>\n    // Apply the saved or system theme before first paint, so a dark user never sees a flash.\n    (function () {\n      try {\n        var stored = localStorage.getItem(\'hero-ops-theme\');\n        var dark = stored ? stored === \'dark\' : matchMedia(\'(prefers-color-scheme: dark)\').matches;\n        if (dark) document.documentElement.classList.add(\'dark\');\n      } catch (e) {}\n    })();\n  </script>\n  <app-root></app-root>',1)
open(p,'w',encoding='utf-8').write(s)
p='src/app/app.html'
s=open(p,encoding='utf-8').read()
s=s.replace("[attr.aria-label]=\"'Notifications'\"","aria-label=\"Notifications\"")
open(p,'w',encoding='utf-8').write(s)
EOF
ls src/app/missions; grep -n "Notifications" src/app/app.html

